// Custom Worker entry: wraps the OpenNext handler with an edge cache for
// the public API routes and exports the Durable Objects.
// @ts-expect-error: generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

// @ts-expect-error: generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache } from "./.open-next/worker.js";
export { IncCacheDO } from "./cloudflare/inc-cache-do";

const EDGE_CACHED_API = ["/api/og", "/api/token-stats", "/api/top-tokens"];
// Public HTML pages are also kept at the edge briefly, so most visits never
// boot Next.js. Edits purge the local copy (lib/edge-cache.ts).
const PAGE_EDGE_TTL = 30;

function isPageRequest(request: Request, url: URL): boolean {
  if (url.pathname.startsWith("/api/") || url.pathname.startsWith("/auth/"))
    return false;
  if (url.pathname.startsWith("/_next/")) return false;
  if (url.searchParams.has("_rsc")) return false;
  const h = request.headers;
  if (h.get("rsc") || h.get("next-router-prefetch") || h.get("next-router-state-tree") || h.get("next-action"))
    return false;
  return true;
}

function edgeTtl(cacheControl: string | null): number {
  if (!cacheControl || /no-store|private/.test(cacheControl)) return 0;
  const m = /s-maxage=(\d+)/.exec(cacheControl);
  return m ? Number(m[1]) : 0;
}

export default {
  async fetch(
    request: Request,
    env: Record<string, unknown>,
    ctx: ExecutionContext
  ): Promise<Response> {
    const url = new URL(request.url);
    // www is the canonical host. API routes (cron, auth) stay on both hosts.
    if (url.hostname === "filtard.com" && !url.pathname.startsWith("/api/")) {
      url.hostname = "www.filtard.com";
      return Response.redirect(url.toString(), 308);
    }
    const isApi = EDGE_CACHED_API.includes(url.pathname);
    const isPage = !isApi && isPageRequest(request, url);
    const cacheable = request.method === "GET" && (isApi || isPage);
    if (!cacheable) return handler.fetch(request, env, ctx);

    const cache = (caches as unknown as { default: Cache }).default;
    const cacheKey = new Request(url.toString(), { method: "GET" });
    const hit = await cache.match(cacheKey);
    if (hit) return hit;

    const res: Response = await handler.fetch(request, env, ctx);
    let ttl = res.status === 200 ? edgeTtl(res.headers.get("Cache-Control")) : 0;
    if (isPage) {
      const html = /text\/html|xml|text\/plain/.test(res.headers.get("Content-Type") || "");
      const personal = res.headers.has("Set-Cookie");
      ttl = html && !personal ? Math.min(ttl, PAGE_EDGE_TTL) : 0;
    }
    if (ttl > 0) {
      const stored = new Response(res.clone().body, res);
      stored.headers.set("Cache-Control", `public, max-age=${ttl}`);
      ctx.waitUntil(cache.put(cacheKey, stored));
    }
    return res;
  },
};
